<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)($_SESSION['role']??'');if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true)){http_response_code(403);exit('Your role cannot view fee invoices.');}$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);$structure=filter_var($_GET['structure_id']??null,FILTER_VALIDATE_INT);$pupil=filter_var($_GET['pupil_id']??null,FILTER_VALIDATE_INT);if(!$school||!$structure||!$pupil){http_response_code(422);exit('Choose a school, fee structure and pupil.');}$db=db();$q=$db->prepare('SELECT s.name school_name,f.id structure_id,f.academic_year,f.term,f.title,f.status,c.name class_name,p.id pupil_id,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level,p.stream,p.status pupil_status FROM schools s JOIN school_memberships m ON m.school_id=s.id AND m.user_id=? JOIN fee_structures f ON f.school_id=s.id AND f.id=? JOIN school_classes c ON c.id=f.class_id AND c.school_id=s.id JOIN pupils p ON p.school_id=s.id AND p.id=? WHERE s.id=?');$q->execute([$uid,$structure,$pupil,$school]);$invoice=$q->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found in an accessible school.');}$q=$db->prepare("SELECT i.description,i.amount,a.ledger_entry_id,l.created_at,r.amount reversed_amount,r.reversal_reason,r.created_at reversed_at FROM fee_assessments a JOIN fee_structure_items i ON i.id=a.item_id AND i.structure_id=a.structure_id AND i.school_id=a.school_id JOIN school_fee_ledger l ON l.id=a.ledger_entry_id AND l.school_id=a.school_id AND l.pupil_id=a.pupil_id LEFT JOIN school_fee_ledger r ON r.reversal_of=l.id AND r.school_id=l.school_id AND r.pupil_id=l.pupil_id AND r.entry_type='charge_reversal' WHERE a.school_id=? AND a.structure_id=? AND a.pupil_id=? ORDER BY i.sequence_no");$q->execute([$school,$structure,$pupil]);$items=$q->fetchAll();if(!$items){http_response_code(404);exit('No ledger-backed invoice lines were found.');}$total=0.0;$reversed=0.0;foreach($items as &$i){$total+=(float)$i['amount'];$reversed+=(float)($i['reversed_amount']??0);}$netInvoice=$total-$reversed;unset($i);$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=? AND academic_year=? AND term=?");$q->execute([$school,$pupil,$invoice['academic_year'],$invoice['term']]);$termBalance=(float)$q->fetchColumn();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee invoice · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>.invoice{max-width:850px;margin:auto}.invoice-number{font:700 14px ui-monospace,monospace}.line-reversed{color:#9b3935}@media print{.sidebar,.topbar,.screen-only,.page-footer{display:none!important}.main-area{margin:0!important;padding:0!important}.page-content{max-width:none!important;padding:0!important}.invoice{box-shadow:none!important;border:0!important}.table-wrap{overflow:visible!important}table{min-width:0!important}}</style></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><div class="crumb">School fees <span>/</span> Invoice</div><button class="button primary screen-only" type="button" onclick="window.print()">Print / Save PDF</button></header><div class="page-content"><section class="content-section invoice"><div class="section-heading"><div><div class="eyebrow"><?=e($invoice['school_name'])?> · <?=e($invoice['class_name'])?></div><h1>Fee invoice</h1><p class="muted"><?=e($invoice['academic_year'].' · '.$invoice['term'])?> · <?=e($invoice['title'])?></p></div><div class="invoice-number">Invoice reference<br>INV-<?=$school?>-<?=$structure?>-<?=$pupil?></div></div><div class="table-wrap"><table><tbody><tr><th>Pupil</th><td><?=e(trim($invoice['first_name'].' '.($invoice['middle_name']??'').' '.$invoice['last_name']))?></td></tr><tr><th>Admission number</th><td><?=e($invoice['admission_number'])?></td></tr><tr><th>Class / stream</th><td><?=e($invoice['class_level'].($invoice['stream']?' · '.$invoice['stream']:''))?></td></tr><tr><th>Account status</th><td><?=e(ucfirst($invoice['pupil_status']))?></td></tr></tbody></table></div><h2>Assessed items</h2><div class="table-wrap"><table><thead><tr><th>Description</th><th>Amount (KES)</th><th>Adjustment</th><th>Net charge (KES)</th></tr></thead><tbody><?php foreach($items as $item):$adjusted=(float)($item['reversed_amount']??0);?><tr><td><?=e($item['description'])?><?php if($adjusted>0):?><div class="line-reversed">Reversed<?=!empty($item['reversal_reason'])?': '.e($item['reversal_reason']):''?></div><?php endif;?></td><td><?=number_format((float)$item['amount'],2)?></td><td><?=number_format($adjusted,2)?></td><td><?=number_format((float)$item['amount']-$adjusted,2)?></td></tr><?php endforeach;?></tbody><tfoot><tr><th>Total</th><th><?=number_format($total,2)?></th><th><?=number_format($reversed,2)?></th><th><?=number_format($netInvoice,2)?></th></tr></tfoot></table></div><section class="metric-grid"><article class="metric-card"><div class="metric-label">NET INVOICE CHARGES</div><div class="metric-value">KES <?=number_format($netInvoice,2)?></div></article><article class="metric-card"><div class="metric-label">CURRENT TERM ACCOUNT BALANCE</div><div class="metric-value">KES <?=number_format($termBalance,2)?></div><div class="metric-note">Includes all charges, payments, discounts and reversals for this term; payments are not allocated to this invoice.</div></article></section><p class="muted">This invoice is derived from fee-structure assessments already recorded in the school ledger. Reversed charges remain shown as adjustments.</p><a class="button screen-only" href="fee_invoices.php?school_id=<?=$school?>&amp;structure_id=<?=$structure?>">Back to invoice register</a></section></div></main></div></body></html>